('transaction-based-revenue-models', 'Transaction-Based Revenue Models: Why Infrastructure Scales When Revenue Follows Usage | NetworkCore', 'Learn why transaction-based revenue models are structurally superior for infrastructure markets, and how NetworkCore applies this principle to EV charging settlement.', '/images/blog/transaction-based-revenue-models.jpg', 'blog'),
('charging-as-a-service-business-model', 'Charging as a Service Business Model | NetworkCore', 'How the charging as a service business model allows platforms to offer EV charging without owning infrastructure, generating passive revenue from every charging session.', '/images/blog/ev-charging-as-a-service.jpg', 'blog'),
