('ev-charging-for-car-rentals', 'EV Charging for Car Rentals | Revenue Layer for Rental Fleets', 'Discover how EV charging for car rentals can become a revenue stream rather than an operational burden. Learn how financial infrastructure transforms rental fleet charging.', '/images/blog/ev-charging-for-car-rentals.jpg', 'blog'),
('mobility-as-a-service', 'Mobility as a Service: Financial Infrastructure for EV Charging | NetworkCore', 'Mobility as a Service only scales when transaction infrastructure is unified. Learn why electrified mobility requires financial clearing and settlement.', '/images/blog/mobility-as-a-service.jpg', 'blog'),
('plug-and-charge-business-model', 'Plug and Charge Business Model | NetworkCore', 'Learn how the Plug and Charge business model transforms EV charging from manual authentication into automated, scalable transaction infrastructure.', '/images/blog/plug-and-charge-business-model.jpg', 'blog'),
('ev-charging-infrastructure-software', 'EV Charging Infrastructure Software | NetworkCore', 'EV charging infrastructure software is a layered stack. Discover the missing financial layer that standardises settlement, pricing, and revenue splits.', '/images/blog/ev-charging-infrastructure-software.jpg', 'blog'),
('who-gets-paid-in-ev-charging', 'Who Gets Paid in EV Charging? | NetworkCore', 'Explore the multi-layered financial structure behind EV charging sessions — who earns, why prices stay high, and how settlement infrastructure brings coherence.', '/images/blog/who-gets-paid-in-ev-charging.jpg', 'blog'),
('super-app-expansion-strategy', 'Super App Expansion Strategy | EV Charging Transaction Layer', 'Why electrified mobility is the next structural layer for super app expansion strategy. Embed EV charging as a high-frequency transaction layer.', '/images/blog/super-app-expansion-strategy.jpg', 'blog'),
('fintech-adjacency-revenue', 'Fintech Adjacency Revenue | EV Charging Transaction Layer', 'Why EV charging is the next logical fintech adjacency revenue opportunity. Embed real-world transactions into existing platforms without infrastructure ownership.', '/images/blog/fintech-adjacency-revenue.png', 'blog'),
