('super-app-revenue-streams', 'Super App Revenue Streams: EV Charging as a Transaction Layer | NetworkCore', 'Why EV charging is a natural next revenue stream for super apps — recurrent, transparent, and scalable through embedded service models.', '/images/blog/super-app-revenue-streams.jpg', 'blog'),
('ev-charging-without-owning-infrastructure', 'EV Charging Without Owning Infrastructure | NetworkCore', 'How Demand Partners can offer EV charging without owning infrastructure — through roaming, settlement, and embedded service models.', '/images/blog/ev-charging-without-owning-infrastructure.jpg', 'blog'),
('fleet-charging-as-a-service', 'Fleet Charging as a Service: Why Fleets Need Access, Not Infrastructure | NetworkCore', 'Discover why fleet charging as a service is replacing infrastructure-first strategies. Learn how fleets can scale EV charging through access, not ownership.', '/images/blog/fleet-charging-as-a-service.jpg', 'blog'),
